<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Product extends Model { protected $fillable=['category_id','sku','name','purchase_price','selling_price','stock','minimum_stock']; public function category(){return $this->belongsTo(Category::class);} public function saleItems(){return $this->hasMany(SaleItem::class);} public function purchaseItems(){return $this->hasMany(PurchaseItem::class);} }
